import './assets/css/styles.styl'
import './assets/css/print.styl'
import './class-component-hooks'
import './plugins/vuetify'
import '@/cs/CSExtensions.ts'
import router from './router'
import {CSToast} from '@/cs/CSToast'
import {Component, Vue} from 'vue-property-decorator'
import {PortalVueBase} from '@/view/PortalVueBase'
import VueMeta from 'vue-meta'

import ToastedPlugin from 'vue-toasted'
import {PortalView} from '@/view/View'
import {doLater} from '@/cs/extensions/CSLang'
import {
  absoluteAssetUrl, canonicalUrl, defaultTitle, fullTitle,
  socialCardHeight, socialCardPath, socialCardWidth
} from '@/model/Seo'
import type {CreateElement, VNode} from 'vue'
import {Locale} from '@/model/content/Locale'
import {activeSeo, ogLocaleFor} from '@/model/content/active'
import {locales} from '@/model/content/Schema'
import {loadGeneratedLocaleCatalog} from '@/model/content/translation/GeneratedLocaleCatalogs'
import {brandName} from '@/model/Brand'

Vue.use(ToastedPlugin)
Vue.use(VueMeta)

Vue.config.productionTip = false

Vue.config.errorHandler = error => {
  CSToast.error(`${error.name} ${error.message}`)
  CSToast.error(`${error.stack}`)
}

@Component({
  router,
  render(createElement: CreateElement): VNode {
    const root = this as PortalVueBase
    return createElement('v-app', {
      props: {dark: root.model.isDarkMode.value}
    }, [
      createElement('v-content', [
        createElement('router-view')
      ])
    ])
  }
})
export class Main extends PortalVueBase {

  isMounted = false
  portal: PortalView | null = null

  mounted() {
    super.mounted()
    this.isMounted = true
  }

  metaInfo(): any {
    const description = this.titles.gatewaySeoDescription
    const image = absoluteAssetUrl(socialCardPath('/'))
    return {
      titleTemplate: (titleChunk: string) => titleChunk ? fullTitle(titleChunk) : defaultTitle(),
      htmlAttrs: {lang: Locale.active},
      meta: [
        {vmid: 'description', name: 'description', content: description},
        {vmid: 'og:site_name', property: 'og:site_name', content: brandName},
        {vmid: 'og:title', property: 'og:title', content: brandName},
        {vmid: 'og:description', property: 'og:description', content: description},
        {vmid: 'og:image', property: 'og:image', content: image},
        {vmid: 'og:image:alt', property: 'og:image:alt', content: brandName},
        {vmid: 'og:image:type', property: 'og:image:type', content: 'image/jpeg'},
        {vmid: 'og:image:width', property: 'og:image:width', content: String(socialCardWidth)},
        {vmid: 'og:image:height', property: 'og:image:height', content: String(socialCardHeight)},
        {vmid: 'og:url', property: 'og:url', content: canonicalUrl('/')},
        {vmid: 'og:type', property: 'og:type', content: 'website'},
        {vmid: 'og:locale', property: 'og:locale', content: activeSeo().ogLocale},
        ...locales.filter(locale => locale !== Locale.active).map(locale => ({
          vmid: `og:locale:alternate-${locale}`,
          property: 'og:locale:alternate',
          content: ogLocaleFor(locale)
        })),
        {vmid: 'twitter:card', name: 'twitter:card', content: 'summary_large_image'},
        {vmid: 'twitter:title', name: 'twitter:title', content: brandName},
        {vmid: 'twitter:description', name: 'twitter:description', content: description},
        {vmid: 'twitter:image', name: 'twitter:image', content: image},
        {vmid: 'twitter:image:alt', name: 'twitter:image:alt', content: brandName}
      ],
      link: [
        {vmid: 'canonical', rel: 'canonical', href: canonicalUrl('/')},
        ...locales.map(locale => ({vmid: `alternate-${locale}`, rel: 'alternate', hreflang: locale, href: canonicalUrl('/', locale)})),
        {vmid: 'alternate-default', rel: 'alternate', hreflang: 'x-default', href: canonicalUrl('/', 'en')}
      ]
    }
  }

}

let main: Main | undefined

/** The root instance, created once the active locale's translations are in place. */
export function mainApp(): Main {
  return main as Main
}

// The page locale is fixed for its lifetime and changing it reloads the page, so
// only the active language is fetched, as its own chunk. English is the source
// content and has nothing to wait for; a failed fetch still starts the app, in
// English, rather than leaving the prerendered snapshot unhydrated. The root is
// built after the translations so its first render is already localized, and the
// system scheme and CSS-owned palette settle before the delayed mount so that
// render matches the prerendered snapshot it replaces.
loadGeneratedLocaleCatalog(Locale.active)
  .catch(() => undefined)
  .then(() => {
    main = new Main()
    main.model.followSystemTheme()
    main.model.loadThemeColors()
    doLater(() => mainApp().$mount('#app'))
  })
